        L.append("")
    L.append("## The Conflict")
    L.append("")
    if n_ent >= 2:
        L.append(f"The headline hides a structural problem: **{below} of {n_ent} economies ({fmt(below_share, 0)}%)** sit at or below the median on *{h}*. The fastest-moving metric in the dataset is *{f}*, which swung **{fmt(fpct, 1)}%** over the period — an early-warning signal that the gap may widen before it narrows.")
    else:
        L.append(f"The tension in this dataset is momentum: *{f}* moved **{fmt(fpct, 1)}%** over the period, the largest swing of any tracked indicator.")
