    L.append("")
    L.append("---")
    L.append("")
    L.append(appendix(primary, found))
    return "\n".join(L)


def main():
    argv = [a for a in sys.argv[1:] if a]
    mode = argv[0] if argv else "generate"
    if mode != "generate":
        print(f"Unknown mode: {mode}", file=sys.stderr)
        return 2
    found = discover()
    primary = pick_primary(found)
    report = build_story(primary, found) if primary else empty_report(found)
    OUTPUT_PATH.write_text(report, encoding="utf-8")

    print("FOUND DATA FILES:")
    for f in found:
        print(f"  - {f['path'].name} (rows={len(f['rows'])}, numeric={len(f['numcols'])}, europe_match={f['eu']})")
