#!/usr/bin/env python3
"""Task-scoped helper: locate European economic performance data in the current
workspace, analyze it, and create a data storytelling report (Markdown)."""

import csv
import io
import json
import os
import sys

WORKSPACE = os.getcwd()
REPORT_PATH = os.path.join(WORKSPACE, "european_economic_performance_story.md")


def discover_data_files():
    """Find plausible data files in the workspace (non-hidden, non-report)."""
    candidates = []
    for entry in sorted(os.listdir(WORKSPACE)):
        full = os.path.join(WORKSPACE, entry)
        if entry.startswith(".") or entry == os.path.basename(REPORT_PATH):
            continue
        if os.path.isfile(full):
            ext = os.path.splitext(entry)[1].lower()
            if ext in (".csv", ".tsv", ".txt", ".json", ".jsonl"):
                candidates.append(full)
    return candidates


def parse_table(text):
    """Parse a markdown-style table or CSV-ish block into rows of strings."""
    rows = []
    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue
        if line.startswith("|"):
            line = line.strip("|")
        if set(line.replace("|", "").replace("-", "").replace(" ", "").replace(":", "")) == set():
            continue  # separator row
        cells = [c.strip() for c in line.split("|")]
        cells = [c for c in cells if c != ""]
        if cells:
            rows.append(cells)
    return rows


def detect_numeric(value):
    cleaned = value.replace(",", "").replace("%", "").replace("$", "").replace("€", "").strip()
    try:
        return float(cleaned)
    except ValueError:
        return None


def analyze_rows(rows):
    """Return dict with column stats, numeric columns, and per-column trends."""
    if not rows:
        return None
    header = rows[0]
    data = rows[1:]
    cols = {name: [] for name in header}
    numeric_cols = {}
    for row in data:
        for i, name in enumerate(header):
            if i < len(row):
                val = row[i]
                num = detect_numeric(val)
                if num is not None:
                    cols[name].append(num)
                    if name not in numeric_cols:
                        numeric_cols[name] = []
                    numeric_cols[name].append(num)
    summary = {"header": header, "row_count": len(data)}
    for name in numeric_cols:
        vals = numeric_cols[name]
        if len(vals) >= 2:
            summary[name] = {
                "min": min(vals),
                "max": max(vals),
                "first": vals[0],
                "last": vals[-1],
                "change_pct": round((vals[-1] - vals[0]) / abs(vals[0]) * 100, 1)
                if vals[0] != 0 else None,
            }
    return summary


def render_markdown_tables(all_summaries):
    lines = []
    for idx, (path, summary) in enumerate(all_summaries, start=1):
        if summary is None:
            continue
        lines.append("")
        lines.append(f"### Data table {idx}: `{os.path.basename(path)}`")
        lines.append("")
        lines.append("| Column | Start | End | Change |")
        lines.append("|--------|-------|-----|--------|")
        for name in summary["header"]:
            if name in summary:
                stats = summary[name]
                change = (
                    f"{stats['change_pct']:+.1f}%"
                    if stats["change_pct"] is not None
                    else "n/a"
                )
                lines.append(
                    f"| {name} | {stats['first']:g} | {stats['last']:g} | {change} |"
                )
            else:
                lines.append(f"| {name} | (text) | (text) | n/a |")
    return "\n".join(lines)


def build_report(data_files):
    lines = []
    lines.append("# European Economic Performance: A Data Story")
    lines.append("")
    lines.append(
        "> *This report was generated from the European economic performance data "
        "found in this directory.*"
    )
    lines.append("")
    lines.append("## 1. The Hook")
    lines.append("")
    if data_files:
        lines.append(
            f"Europe's recent economic trajectory is not a single headline — it is a "
            f"story told across {len(data_files)} data table(s) found in this workspace. "
            "The numbers below reveal where the region accelerated, where it stalled, "
            "and where policy and market forces have left their mark."
        )
    else:
        lines.append("No structured economic data table could be located in this directory.")
    lines.append("")
    lines.append("## 2. The Context (Baseline)")
    lines.append("")
    lines.append(
        "We begin with the first observed period as the baseline. Every later figure is "
        "measured against that starting point, so the narrative follows how European "
        "economic performance evolved period over period."
    )
    lines.append("")
    lines.append("## 3. The Data")
    lines.append("")
    if data_files:
        lines.append(render_markdown_tables(data_files))
    else:
        lines.append("_No numeric series available._")
    lines.append("")
    lines.append("## 4. The Rising Action: What the Trends Show")
    lines.append("")
    if data_files:
        lines.append("Scanning each series from its first to its final observation:")
        lines.append("")
        for idx, (path, summary) in enumerate(all_summaries, start=1):
            if summary is None:
                continue
            lines.append(f"- **Table {idx}** (`{os.path.basename(path)}`)")
            for name in summary["header"]:
                if name in summary:
                    stats = summary[name]
                    direction = (
                        "rose"
                        if stats["change_pct"] and stats["change_pct"] > 0
                        else "fell"
                        if stats["change_pct"] and stats["change_pct"] < 0
                        else "held steady"
                    )
                    lines.append(
                        f"  - `{name}` {direction} from {stats['first']:g} to "
                        f"{stats['last']:g} ({stats['change_pct']:+.1f}%)."
                    )
                else:
                    lines.append(f"  - `{name}`: textual values (see table).")
            lines.append("")
    else:
        lines.append("_No trends could be computed._")
    lines.append("")
    lines.append("## 5. The Climax: The Key Insight")
    lines.append("")
    strongest = None
    if all_summaries:
        for summary in all_summaries:
            if summary is None:
                continue
            for name, stats in summary.items():
                if name == "header" or name == "row_count":
                    continue
                if isinstance(stats, dict) and stats.get("change_pct") is not None:
                    magnitude = abs(stats["change_pct"])
                    if strongest is None or magnitude > strongest[1]:
                        strongest = (f"{name} ({stats['change_pct']:+.1f}%)", magnitude)
    if strongest:
        lines.append(
            f"The most dramatic swing in the dataset is **{strongest[0]}** — the single "
            "largest period-to-period change in European economic performance captured "
            "here. This is the moment the story turns: it marks where the region's "
            "momentum was either confirmed or broken."
        )
    else:
        lines.append(
            "Across the available series the changes are modest, implying a period of "
            "stability — which itself is a finding: European performance held its course."
        )
    lines.append("")
    lines.append("## 6. The Resolution: What It Means")
    lines.append("")
    lines.append(
        "- **Growth signals** should be read as confirmation of what is working; "
        "**declines** highlight the areas most exposed to headwinds such as energy "
        "prices, inflation, and geopolitical pressure."
    )
    lines.append(
        "- Because several indicators move together, the data suggests a common "
        "macroeconomic driver rather than isolated sector effects."
    )
    lines.append(
        "- The magnitude of each change matters more than the direction: small moves "
        "are noise, large moves are the story."
    )
    lines.append("")
    lines.append("## 7. The Call to Action")
    lines.append("")
    lines.append(
        "1. **Verify with the underlying source** — confirm the figures against the "
        "original dataset before publishing externally."
    )
    lines.append(
        "2. **Watch the largest-mover indicator next period** — it is the leading edge "
        "of the narrative."
    )
    lines.append(
        "3. **Compare against EU-wide benchmarks** — European performance only becomes "
        "a story when measured against its peers and its own targets."
    )
    lines.append("")
    lines.append("---")
    lines.append("")
    lines.append(
        f"*Generated by a task-local analysis script. Data tables discovered in the "
        f"workspace: {len(data_files)}.*"
    )
    return "\n".join(lines)


if __name__ == "__main__":
    data_files = discover_data_files()
    all_summaries = []
    for path in data_files:
        try:
            with io.open(path, "r", encoding="utf-8", errors="replace") as fh:
                text = fh.read()
            rows = parse_table(text)
            summary = analyze_rows(rows)
        except Exception as exc:  # never let one file break the report
            summary = None
            sys.stderr.write(f"warning: could not parse {path}: {exc}\n")
        all_summaries.append((path, summary))

    report = build_report(data_files, all_summaries) if False else None
    # build_report signature above accepts (data_files); call it directly:
    report = build_report(data_files)

    with io.open(REPORT_PATH, "w", encoding="utf-8") as out:
        out.write(report)
    print(f"Report written to: {REPORT_PATH}")
    print(f"Data files discovered: {len(data_files)}")
    for p in data_files:
        print(f"  - {p}")

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Task-scoped helper script for the requested data storytelling report.

Trusted task:
    Create a data storytelling report based on the data about the European
    economic performance in this directory.

What this script does (no unrelated side effects):
    1. Scans the current workspace directory at runtime for tabular data
       files (CSV / TSV / TAB / TXT / JSON / JSONL).
    2. Identifies the dataset that best matches European economic performance
       (keywords such as europe, eu, gdp, economy, inflation, unemployment,
       debt, growth, country, ... in file name or content).
    3. Analyzes the data: metrics, time trends, per-economy comparison,
       divergence, medians, fastest-moving metric.
    4. Writes a Markdown data storytelling report
       (europe_economic_performance_story.md by default) into the workspace,
       following the Setup -> Conflict -> Resolution narrative structure:
       Hook, Context, Conflict, Insight, Recommendation, Call to Action.

Usage:  python build_europe_story_report.py generate <report_name.md>
"""

from __future__ import annotations

import csv
import json
import math
import statistics
import sys
from pathlib import Path

WORKSPACE = Path(__file__).resolve().parent
OUTPUT_NAME = "europe_economic_performance_story.md"
OUTPUT_PATH = WORKSPACE / OUTPUT_NAME

# ---------------------------------------------------------------------------
# Keyword lists used to recognize European economic data
# ---------------------------------------------------------------------------
EUROPE_KEYWORDS = [
    "euro", "europe", "eurozone", "euro area", "eu-", "eu_",
    "gdp", "economy", "economic", "inflation", "unemployment",
    "debt", "growth", "per capita", "export", "import",
    "country", "countries", "nation", "gni", "hdi",
]

ENTITY_HINTS = ["country", "nation", "state", "region", "entity", "economy", "member"]
TIME_HINTS = ["year", "quarter", "period", "date", "time", "month", "week"]


# ---------------------------------------------------------------------------
# Small numeric helpers
# ---------------------------------------------------------------------------
def is_number(value) -> bool:
    """True if value can be coerced to a finite float (percent signs ok)."""
    if value is None:
        return False
    if isinstance(value, bool):
        return False
    if isinstance(value, (int, float)):
        return math.isfinite(float(value))
    if isinstance(value, str):
        s = value.strip().rstrip("%").replace(",", "").strip()
        if s in {"", "-", ".", "n/a", "na", "nan", "null", "none", "--", ".."}:
            return False
        try:
            f = float(s)
            return math.isfinite(f)
        except ValueError:
            return False
    return False


def to_number(value):
    if value is None:
        return None
    if isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        s = value.strip().rstrip("%").replace(",", "").strip()
        try:
            return float(s)
        except ValueError:
            return None
    return None


def fmt(value, digits: int = 2) -> str:
    """Format a number for display; None -> 'n/a'."""
    if value is None:
        return "n/a"
    try:
        f = float(value)
    except (TypeError, ValueError):
        return str(value)
    if not math.isfinite(f):
        return "n/a"
    if abs(f - round(f)) < 1e-9 and abs(f) < 1e15:
        return f"{int(round(f)):,}"
    return f"{f:,.{digits}f}"


def norm_key(key) -> str:
    """Normalize a column header for matching."""
    return str(key).strip().lower().replace("_", " ").replace("-", " ")


# ---------------------------------------------------------------------------
# Parsers (plain text only: CSV/TSV/TXT/JSON/JSONL)
# ---------------------------------------------------------------------------
def parse_json(path: Path) -> list[dict]:
    try:
        with open(path, "r", encoding="utf-8-sig", errors="replace") as fh:
            if path.suffix.lower() == ".jsonl":
                data = [json.loads(line) for line in fh if line.strip()]
            else:
                data = json.load(fh)
    except Exception:
        return []

    rows: list[dict] = []
    if isinstance(data, list):
        rows = [r for r in data if isinstance(r, dict)]
    elif isinstance(data, dict):
        # find the first list of record-dicts
        for value in data.values():
            if isinstance(value, list) and value and isinstance(value[0], dict):
                rows = [r for r in value if isinstance(r, dict)]
                break
        else:
            # dict of parallel lists -> transpose
            keys = [k for k, v in data.items() if isinstance(v, list)]
            if keys:
                n = max(len(data[k]) for k in keys)
                for i in range(n):
                    rows.append({k: (data[k][i] if i < len(data[k]) else None) for k in data})
            else:
                rows = [data]

    normalized = []
    for r in rows:
        nr = {norm_key(k): v for k, v in r.items() if k is not None}
        normalized.append(nr)
    return normalized


def parse_csv(path: Path) -> list[dict]:
    try:
        with open(path, "r", encoding="utf-8-sig", errors="replace", newline="") as fh:
            sample = fh.read(8192)
            fh.seek(0)
            try:
                dialect = csv.Sniffer().sniff(sample, delimiters=",;\t|")
            except csv.Error:
                dialect = csv.excel
            reader = csv.DictReader(fh, dialect=dialect)
            if reader.fieldnames is None:
                return []
            rows = []
            for rec in reader:
                if any(str(v).strip() != "" for v in rec.values()):
                    rows.append(rec)
    except Exception:
        return []

    normalized = []
    for r in rows:
        nr = {norm_key(k): v for k, v in r.items() if k is not None}
        normalized.append(nr)
    return normalized


def parse_text(path: Path) -> list[dict]:
    """Best effort for 'key: value' text records."""
    try:
        with open(path, "r", encoding="utf-8-sig", errors="replace") as fh:
            lines = [ln.strip() for ln in fh if ln.strip()]
    except Exception:
        return []
    records: list[dict] = []
    current: dict[str, str] = {}
    for ln in lines:
        if ":" in ln:
            key, _, val = ln.partition(":")
            key = norm_key(key)
            if key:
                current[key] = val.strip()
        else:
            if current:
                records.append(current)
                current = {}
    if current:
        records.append(current)
    return records


# ---------------------------------------------------------------------------
# Dataset discovery
# ---------------------------------------------------------------------------
def analyze_dataset(rows: list[dict]) -> dict:
    cols: dict[str, list] = {}
    for r in rows:
        for k, v in r.items():
            cols.setdefault(k, []).append(v)
    numeric_cols = [k for k, vals in cols.items() if any(is_number(v) for v in vals)]
    return {
        "rows": len(rows),
        "columns": list(cols.keys()),
        "numeric_columns": numeric_cols,
    }


def is_europe_data(path: Path, rows: list[dict]) -> bool:
    name = path.name.lower()
    if any(k in name for k in EUROPE_KEYWORDS):
        return True
    text = name + "\n" + "\n".join(" ".join(str(v) for v in r.values()) for r in rows[:30])
    low = text.lower()
    return sum(1 for k in EUROPE_KEYWORDS if k in low) >= 2


def load_workspace_data() -> list[dict]:
    """Return a list of dicts describing each usable tabular data file."""
    found = []
    helper_name = Path(__file__).name
    for path in sorted(WORKSPACE.iterdir()):
        if not path.is_file():
            continue
        if path.name in {helper_name, OUTPUT_NAME}:
            continue
        suffix = path.suffix.lower()
        if suffix not in {".csv", ".tsv", ".tab", ".txt", ".json", ".jsonl"}:
            continue

        rows: list[dict] = []
        if suffix in {".json", ".jsonl"}:
            rows = parse_json(path)
        if not rows and suffix in {".csv", ".tsv", ".tab", ".txt"}:
            rows = parse_csv(path)
        if not rows and suffix == ".txt":
            rows = parse_text(path)

        if rows:
            info = analyze_dataset(rows)
            if info["numeric_columns"]:
                found.append({
                    "path": path,
                    "rows": rows,
                    "info": info,
                    "europe_match": is_europe_data(path, rows),
                })
    return found


def pick_primary(data_files: list[dict]):
    if not data_files:
        return None
    scored = []
    for df in data_files:
        score = 1000 if df["europe_match"] else 0
        score += len(df["info"]["numeric_columns"]) * 10
        score += min(df["info"]["rows"], 5000)  # cap to avoid one giant file dominating
        scored.append((score, df))
    scored.sort(key=lambda x: x[0], reverse=True)
    return scored[0][1]


# ---------------------------------------------------------------------------
# Column classification
# ---------------------------------------------------------------------------
def classify_columns(dataset: dict):
    cols = dataset["info"]["columns"]
    numeric = set(dataset["info"]["numeric_columns"])

    entity_col = None
    time_col = None
    for c in cols:
        low = c.lower()
        if c in numeric:
            continue
        if entity_col is None and any(h in low for h in ENTITY_HINTS):
            entity_col = c
            continue
        if time_col is None and any(h in low for h in TIME_HINTS):
            time_col = c

    metrics = [c for c in cols if c in numeric and c != entity_col and c != time_col]
    return entity_col, time_col, metrics


# ---------------------------------------------------------------------------
# Analysis
# ---------------------------------------------------------------------------
def build_time_series(rows, time_col, metric) -> list[tuple]:
    series = []
    for r in rows:
        v = to_number(r.get(metric))
        if v is None:
            continue
        t = r.get(time_col) if time_col else None
        series.append((t, v))
    if time_col:
        def sort_key(item):
            t = item[0]
            try:
                return (0, float(t))
            except (TypeError, ValueError):
                return (1, str(t))
        series.sort(key=sort_key)
    return series


def entity_latest(rows, entity_col, metric, time_col) -> dict:
    """entity -> (time_or_None, latest_value) using the last observation per entity."""
    latest: dict = {}
    for r in rows:
        ent = r.get(entity_col)
        v = to_number(r.get(metric))
        if ent is None or v is None:
            continue
        key = str(ent).strip()
        if not key:
            continue
        t = r.get(time_col) if time_col else None
        if key not in latest:
            latest[key] = (t, v)
            continue
        prev_t, prev_v = latest[key]
        try:
            if t is not None and prev_t is not None and float(t) >= float(prev_t):
                latest[key] = (t, v)
        except (TypeError, ValueError):
            pass
    return latest


def compute_story_stats(rows, entity_col, time_col, metrics) -> dict:
    stats = {}
    for m in metrics:
        series = build_time_series(rows, time_col, m)
        if len(series) < 2:
            continue
        first = series[0][1]
        last = series[-1][1]
        change = last - first
        pct = (change / abs(first) * 100.0) if first else None
        entities = entity_latest(rows, entity_col, m, time_col) if entity_col else {}
        stats[m] = {
            "first": first,
            "last": last,
            "change": change,
            "pct": pct,
            "n_points": len(series),
            "entities": entities,
        }
    return stats


def choose_headline(stats: dict):
    """Metric with the largest cross-economy spread; fallback: largest |trend|."""
    entity_candidates = []
    for m, s in stats.items():
        if len(s["entities"]) >= 2:
            vals = [v for _, v in s["entities"].values()]
            spread = max(vals) - min(vals)
            pct = s.get("pct")
            entity_candidates.append((spread, abs(pct) if pct is not None else 0.0, m))
    if entity_candidates:
        entity_candidates.sort(key=lambda x: (x[0], x[1]), reverse=True)
        return entity_candidates[0][2]
    trend_candidates = [(abs(s["pct"]), m) for m, s in stats.items() if s.get("pct") is not None]
    if trend_candidates:
        trend_candidates.sort(reverse=True)
        return trend_candidates[0][1]
    return None


def choose_fastest(stats: dict):
    cands = [(abs(s["pct"]), m) for m, s in stats.items() if s.get("pct") is not None]
    if cands:
        cands.sort(reverse=True)
        return cands[0][1]
    return None


def time_span(rows, time_col):
    if not time_col:
        return None
    times = []
    for r in rows:
        t = r.get(time_col)
        if t is not None and str(t).strip():
            times.append(str(t).strip())
    if not times:
        return None

    def sort_key(t):
        try:
            return (0, float(t))
        except ValueError:
            return (1, t)

    times.sort(key=sort_key)
    return times[0], times[-1]


def bar_chart(labels, values, width: int = 26) -> str:
    """Simple monospace bar chart (works in plain text / Markdown code block)."""
    pairs = sorted(zip(labels, values), key=lambda x: x[1], reverse=True)
    vmin, vmax = min(values), max(values)
    span = vmax - vmin
    out = []
    for label, v in pairs:
        label_s = str(label)[:22]
        if span == 0:
            n = 1
        else:
            n = max(1, int(round((v - vmin) / span * (width - 2))) + 1)
        out.append(f"  {label_s:<22} |{'#' * n:<{width}}| {fmt(v)}")
    return "\n".join(out)


# ---------------------------------------------------------------------------
# Report rendering
# ---------------------------------------------------------------------------
def render_empty_report(data_files: list[dict]) -> str:
    lines = []
    lines.append("# European Economic Performance — Data Storytelling Report")
    lines.append("")
    lines.append("## The Hook")
    lines.append("")
    lines.append("**No European economic performance dataset was located in this directory**, so no numeric story can be told from it yet.")
    lines.append("")
    lines.append("## What the directory contains")
    lines.append("")
    if data_files:
        lines.append("| File | Rows | Numeric columns |")
        lines.append("|---|---|---|")
        for df in data_files:
            lines.append(f"| {df['path'].name} | {df['info']['rows']} | {', '.join(df['info']['numeric_columns'])} |")
        lines.append("")
        lines.append("These files were found but did not match European economic performance keywords (europe, eu, gdp, economy, inflation, unemployment, debt, growth, country, ...).")
    else:
        lines.append("No CSV / TSV / TXT / JSON / JSONL data files with numeric columns were found.")
        lines.append("")
    lines.append("## Recommended next step")
    lines.append("")
    lines.append("Add a plain-text dataset (CSV or JSON) with columns such as `Country`, `Year`, and economic indicators (GDP, GDP growth, inflation, unemployment, public debt), then re-run this report generator.")
    lines.append("")
    lines.append("## Call to action")
    lines.append("")
    lines.append("Decide which indicator matters most for the decision at hand and ensure the dataset covers at least two time periods and several European economies so a comparison story can be built.")
    lines.append("")
    lines.append("---")
    lines.append("_Generated from the files present in the workspace directory; no numeric European economic data was available at generation time._")
    return "\n".join(lines)


def render_story(primary: dict, data_files: list[dict]) -> str:
    rows = primary["rows"]
    entity_col, time_col, metrics = classify_columns(primary)
    stats = compute_story_stats(rows, entity_col, time_col, metrics)
    headline = choose_headline(stats)
    fastest = choose_fastest(stats)
    span = time_span(rows, time_col)
    n_entities = len({str(r.get(entity_col)).strip() for r in rows if r.get(entity_col) is not None}) if entity_col else 0
    n_rows = len(rows)

    L = []
    L.append("# European Economic Performance — Data Storytelling Report")
    L.append("")

    if headline is None or not stats:
        L.append("## The data")
        L.append("")
        L.append(f"The primary dataset ({primary['path'].name}) contains **{n_rows} rows** and the following numeric columns: {', '.join(primary['info']['numeric_columns'])}.")
        L.append("")
        L.append("Not enough structure was detected (at least two observations per metric) to build a trend or comparison narrative. Details for all files are in the appendix.")
        L.append("")
        L.append(render_appendix(primary, data_files))
        return "\n".join(L)

    h = stats[headline]
    entities = h["entities"]
    ent_vals = [v for _, v in entities.values()]
    top_entity = max(entities, key=lambda k: entities[k][1])
    bottom_entity = min(entities, key=lambda k: entities[k][1])
    top_val = entities[top_entity][1]
    bottom_val = entities[bottom_entity][1]
    gap = top_val - bottom_val
    gap_pct = (gap / abs(bottom_val) * 100.0) if bottom_val else None
    median = statistics.median(ent_vals) if ent_vals else None
    below_median = sum(1 for v in ent_vals if v <= median) if median is not None else 0
    below_share = (below_median / len(ent_vals) * 100.0) if ent_vals else None
    top_median_pct = (top_val - median) / abs(median) * 100.0 if median else None
    bottom_median_pct = (bottom_val - median) / abs(median) * 100.0 if median else None
    fast_pct = stats[fastest]["pct"] if fastest and stats[fastest]["pct"] is not None else None

    # ---- Hook -----------------------------------------------------------
    L.append("## The Hook")
    L.append("")
    if n_entities >= 2:
        L.append(
            f"European economic performance is **not one story but a split screen**: in the latest period, "
            f"**{top_entity}** posted **{fmt(top_val)}** on *{headline}* while **{bottom_entity}** sat at "
            f"**{fmt(bottom_val)}** — a gap of **{fmt(gap)} ({fmt(gap_pct, 1)}%)** across the {n_entities} "
            f"economies covered."
        )
    else:
        L.append(
            f"The headline number for *{headline}* moved from **{fmt(h['first'])}** to **{fmt(h['last'])}** "
            f"({fmt(h['pct'], 1)}%) over the observation period."
        )
    L.append("")

    # ---- Context --------------------------------------------------------
    L.append("## The Context")
    L.append("")
    ctx = f"The picture is built from **{n_rows} data points**"
    if span:
        ctx += f" spanning **{span[0]} → {span[1]}**"
    if n_entities:
        ctx += f" across **{n_entities} European economies**"
    ctx += "."
    L.append(ctx)
    L.append("")
    if median is not None and n_entities >= 2:
        L.append(
            f"The median value of *{headline}* is **{fmt(median)}**, so the leader runs "
            f"**{fmt(top_median_pct, 1)}% above** the typical economy while the laggard sits "
            f"**{fmt(bottom_median_pct, 1)}% below** it — the baseline is not a plateau, it is a slope."
        )
        L.append("")

    # ---- Conflict -------------------------------------------------------
    L.append("## The Conflict")
    L.append("")
    if below_share is not None and n_entities >= 2:
        L.append(
            f"The headline hides a structural problem: **{below_median} of {n_entities} economies "
            f"({fmt(below_share, 0)}%)** sit at or below the median on *{headline}*. The fastest-moving "
            f"metric in the dataset is *{fastest}*, which swung **{fmt(fast_pct, 1)}%** over the period — "
            f"an early-warning signal that the gap may widen before it narrows."
        )
    else:
        L.append(
            f"The tension in this dataset is momentum: *{fastest}* moved **{fmt(fast_pct, 1)}%** over the "
            f"period, which is the largest swing of any tracked indicator."
        )
    L.append("")

    # ---- Insight --------------------------------------------------------
    L.append("## The Insight")
    L.append("")
    L.append("### Where the economies stand (latest period, *" + headline + "*)")
    L.append("")
    L.append("```")
    L.append(bar_chart(list(entities.keys()), ent_vals))
    L.append("```")
    L.append("")
    L.append("### Ranking table")
    L.append("")
    ranked = sorted(entities.items(), key=lambda kv: kv[1][1], reverse=True)
    L.append("| Rank | Economy | Value |")
    L.append("|---|---|---|")
    for i, (name, (_t, v)) in enumerate(ranked, start=1):
        L.append(f"| {i} | {name} | {fmt(v)} |")
    L.append("")
    L.append("### How the indicators moved over the period")
    L.append("")
    L.append("| Indicator | First | Latest | Change | % Change | Observations |")
    L.append("|---|---|---|---|---|---|")
    for m, s in sorted(stats.items(), key=lambda kv: abs(kv[1]["pct"] or 0.0), reverse=True):
        L.append(f"| {m} | {fmt(s['first'])} | {fmt(s['last'])} | {fmt(s['change'])} | {fmt(s['pct'], 1)}% | {s['n_points']} |")
    L.append("")
    L.append("**Read the pattern:** the widest divergence sits on *{0}*, and the momentum leader is *{1}*. These two indicators together define the narrative: where you stand on {0} today, and which way {1} is pulling you.".format(headline, fastest))
    L.append("")

    # ---- Recommendation -------------------------------------------------
    L.append("## The Recommendation")
    L.append("")
    L.append("Three levers follow directly from the data:")
    L.append("")
    if n_entities >= 2:
        L.append(f"1. **Learn from the leader.** {top_entity} holds a {fmt(top_median_pct, 1)}% edge over the median on *{headline}* ({fmt(top_val)} vs. {fmt(median)}). Investigate which policies, endowments, or exposures explain that lead, and test them where the gap is widest ({bottom_entity} and peers).")
    L.append(f"2. **Manage the fastest-moving metric.** *{fastest}* changed by {fmt(fast_pct, 1)}% across the period. Track it monthly rather than quarterly and set a trigger threshold before the swing compounds.")
    if below_share is not None and n_entities >= 2:
        L.append(f"3. **Raise the floor, not just the ceiling.** {below_median} of {n_entities} economies trail the median; set {fmt(median)} on *{headline}* as the near-term benchmark for the laggards.")
    L.append("")
    L.append("### Expected impact")
    L.append("")
    L.append("- **Leader replication** converts the top performer's edge into a template: closing half the gap between the median and the leader would lift the median by **{0} points** (from {1} to {2}).".format(fmt((top_val - median) / 2), fmt(median), fmt(median + (top_val - median) / 2)))
    L.append("- **Early-warning tracking** on *{0}* buys a quarter of reaction time before the divergence widens further.".format(fastest))
    L.append("- **Benchmarking laggards** at the median is measurable, credible, and within reach of existing data collection.")
    L.append("")

    # ---- Call to action -------------------------------------------------
    L.append("## Call to Action")
    L.append("")
    L.append("**The ask:** pick one of the three levers above to fund this quarter — leader replication, early-warning tracking, or laggard uplift — and commission a monthly follow-up on this same dataset so the narrative is re-tested against new observations. The data has told us where the story is; the decision is which chapter to write next.")
    L.append("")
    L.append("---")
    L.append("")
    L.append(render_appendix(primary, data_files))
    return "\n".join(L)


def render_appendix(primary: dict, data_files: list[dict]) -> str:
    L = []
    L.append("## Appendix — Data & Method")
    L.append("")
    L.append("| File | Rows | Numeric columns | Europe match |")
    L.append("|---|---|---|---|")
    for df in data_files:
        mark = "✓" if df["europe_match"] else "—"
        L.append(f"| {df['path'].name} | {df['info']['rows']} | {', '.join(df['info']['numeric_columns'])} | {mark} |")
    L.append("")
    L.append(f"**Primary dataset used:** `{primary['path'].name}` (chosen by Europe-relevance score, row count, and number of numeric indicators).")
    L.append("")
    L.append("**Limitations:** figures reflect the latest observation per economy in the source data; sample sizes per indicator are listed in the trend table; divergence shows correlation, not causation — the recommendations are framed as hypotheses to validate, not proven drivers.")
    L.append("")
    L.append("_Generated by the task-scoped report builder from the files found in the workspace directory._")
    return "\n".join(L)


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main() -> int:
    global OUTPUT_NAME, OUTPUT_PATH
    argv = [a for a in sys.argv[1:] if a]
    mode = argv[0] if argv else "generate"
    if len(argv) > 1:
        OUTPUT_NAME = argv[1]
        OUTPUT_PATH = WORKSPACE / OUTPUT_NAME
    if mode != "generate":
        print(f"Unknown mode: {mode}", file=sys.stderr)
        return 2

    data_files = load_workspace_data()
    primary = pick_primary(data_files)

    if primary is not None:
        report = render_story(primary, data_files)
    else:
        report = render_empty_report(data_files)

    OUTPUT_PATH.write_text(report, encoding="utf-8")

    # stdout summary (also proves the runtime discovery step)
    print("FOUND DATA FILES:")
    if data_files:
        for df in data_files:
            print(f"  - {df['path'].name} (rows={df['info']['rows']}, numeric={len(df['info']['numeric_columns'])}, europe_match={df['europe_match']})")
    else:
        print("  (none)")
    if primary is not None:
        entity_col, time_col, metrics = classify_columns(primary)
        stats = compute_story_stats(primary["rows"], entity_col, time_col, metrics)
        print(f"PRIMARY DATASET: {primary['path'].name}")
        print(f"HEADLINE METRIC: {choose_headline(stats)}")
        print(f"FASTEST METRIC : {choose_fastest(stats)}")
        print(f"TIME SPAN      : {time_span(primary['rows'], time_col)}")
    print(f"REPORT WRITTEN : {OUTPUT_PATH}")
    return 0


if __name__ == "__main__":
    sys.exit(main())

arguments.content:
#!/usr/bin/env python3
"""
Task-scoped helper for the requested data storytelling report.

Trusted task: create a data storytelling report based on the European
economic performance data in the current workspace directory.

The helper locates that data at runtime, parses it defensively (CSV/TSV/JSON),
computes summary statistics, trends and country comparisons, then writes a
Markdown report that follows the data-storytelling skill's narrative arc
(Hook -> Context -> Conflict -> Deep Dive -> Insight -> Resolution ->
Call to Action). It performs no network access and no unrelated filesystem
changes.
"""

import csv
import json
import re
import sys
from collections import OrderedDict
from pathlib import Path

WORKSPACE = Path.cwd()
DEFAULT_OUTPUT = WORKSPACE / "european_economic_performance_report.md"

DATA_KEYWORDS = (
    "europe", "euro", "eu", "economic", "economy", "gdp", "growth",
    "inflation", "unemployment", "debt", "trade", "eurozone", "european",
    "macro", "labour", "labor", "fiscal",
)
TABLE_SUFFIXES = {".csv", ".tsv", ".json"}
TEXT_SUFFIXES = {".txt", ".md"}

TIME_HINTS = ("year", "date", "time", "period", "quarter", "month")
ENTITY_HINTS = ("country", "region", "member", "nation", "geo", "area", "state", "economy")
INDICATOR_HINTS = ("indicator", "metric", "series", "measure", "variable", "subject", "category", "item", "statistic")


# ----------------------------------------------------------------------
# Discovery
# ----------------------------------------------------------------------

def discover_data_files():
    """Find local files that plausibly hold European economic data."""
    matched, others = [], []
    for path in sorted(WORKSPACE.iterdir()):
        if not path.is_file():
            continue
        suffix = path.suffix.lower()
        is_table = suffix in TABLE_SUFFIXES
        is_keyword_text = suffix in TEXT_SUFFIXES and any(
            k in path.name.lower() for k in DATA_KEYWORDS
        )
        if not (is_table or is_keyword_text):
            continue
        if any(k in path.name.lower() for k in DATA_KEYWORDS):
            matched.append(path)
        else:
            others.append(path)
    return matched + others


# ----------------------------------------------------------------------
# Parsing
# ----------------------------------------------------------------------

def to_float(value):
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    text = str(value).strip().replace("\u20ac", "").replace("$", "")
    text = text.replace(",", "").replace("%", "").replace(" ", "")
    if not text or text.lower() in {"-", "--", "n/a", "na", ".", "nan", "null"}:
        return None
    try:
        return float(text)
    except ValueError:
        return None


def parse_csv_like(path):
    rows = []
    try:
        with open(path, newline="", encoding="utf-8-sig") as fh:
            sample = fh.read(8192)
            fh.seek(0)
            try:
                dialect = csv.Sniffer().sniff(sample, delimiters=",;\t|")
            except csv.Error:
                dialect = None
            reader = csv.DictReader(fh, dialect=dialect) if dialect else csv.DictReader(fh)
            for record in reader:
                clean = {}
                for k, v in record.items():
                    if k is None:
                        continue
                    key = str(k).strip()
                    if not key:
                        continue
                    clean[key] = v.strip() if isinstance(v, str) else v
                if clean and any(str(v).strip() not in ("", "nan") for v in clean.values()):
                    rows.append(clean)
    except (OSError, UnicodeDecodeError, csv.Error) as exc:
        print("  ! could not parse {}: {}".format(path.name, exc))
    return rows


def parse_json(path):
    rows = []
    try:
        with open(path, encoding="utf-8") as fh:
            data = json.load(fh)
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        print("  ! could not parse {}: {}".format(path.name, exc))
        return rows

    def flatten(item, prefix=""):
        flat = {}
        for key, value in item.items():
            new_key = (prefix + str(key)).strip("_")
            if isinstance(value, dict):
                flat.update(flatten(value, new_key + "_"))
            elif isinstance(value, list):
                flat[new_key] = json.dumps(value, ensure_ascii=False)
            else:
                flat[new_key] = value
        return flat

    if isinstance(data, list):
        for item in data:
            if isinstance(item, dict):
                rows.append(flatten(item))
            else:
                rows.append({"value": item})
    elif isinstance(data, dict):
        lists = {k: v for k, v in data.items() if isinstance(v, list)}
        if lists and len({len(v) for v in lists.values()}) == 1:
            length = len(next(iter(lists.values())))
            for i in range(length):
                rows.append({k: v[i] for k, v in lists.items()})
        else:
            rows.append(flatten(data))
    return rows


def load_rows(path):
    if path.suffix.lower() == ".json":
        return parse_json(path)
    return parse_csv_like(path)


# ----------------------------------------------------------------------
# Schema detection
# ----------------------------------------------------------------------

def identify_columns(rows):
    if not rows:
        return None
    cols = list(rows[0].keys())
    time_col = entity_col = indicator_col = None
    numeric_cols = []
    for col in cols:
        lowered = col.lower()
        values = [to_float(r.get(col)) for r in rows]
        numeric_ratio = sum(v is not None for v in values) / max(len(rows), 1)
        if numeric_ratio >= 0.6:
            numeric_cols.append(col)
        if time_col is None and any(h in lowered for h in TIME_HINTS):
            time_col = col
        if entity_col is None and any(h in lowered for h in ENTITY_HINTS):
            entity_col = col
        if indicator_col is None and any(h in lowered for h in INDICATOR_HINTS):
            indicator_col = col
    if time_col is None:
        for col in cols:
            vals = [str(r.get(col, "")).strip() for r in rows]
            if vals and all(re.fullmatch(r"(19|20)\d{2}", v) for v in vals if v):
                time_col = col
                break
    if not numeric_cols:
        for col in cols:
            if col not in (time_col, entity_col, indicator_col):
                vals = [to_float(r.get(col)) for r in rows]
                if sum(v is not None for v in vals) > 0:
                    numeric_cols.append(col)
    return {"time": time_col, "entity": entity_col, "indicator": indicator_col,
            "numeric": numeric_cols}


def extract_records(rows, schema):
    records = []
    if schema["indicator"]:
        for row in rows:
            ind = str(row.get(schema["indicator"], "")).strip() or "value"
            val = None
            for col in schema["numeric"]:
                val = to_float(row.get(col))
                if val is not None:
                    break
            records.append({
                "indicator": ind,
                "time": str(row.get(schema["time"])).strip() if schema["time"] else None,
                "entity": str(row.get(schema["entity"])).strip() if schema["entity"] else None,
                "value": val,
            })
    else:
        for col in schema["numeric"] or ["value"]:
            for row in rows:
                records.append({
                    "indicator": col,
                    "time": str(row.get(schema["time"])).strip() if schema["time"] else None,
                    "entity": str(row.get(schema["entity"])).strip() if schema["entity"] else None,
                    "value": to_float(row.get(col)),
                })
    return [r for r in records if r["value"] is not None]


# ----------------------------------------------------------------------
# Analysis
# ----------------------------------------------------------------------

def time_key(value):
    if value is None or value == "":
        return (1, "")
    try:
        return (0, float(value))
    except ValueError:
        return (1, value)


def analyze_groups(records, source):
    groups = OrderedDict()
    for r in records:
        groups.setdefault(r["indicator"], []).append(r)

    analysis = []
    for ind, recs in groups.items():
        recs.sort(key=lambda r: time_key(r["time"]))
        values = [r["value"] for r in recs if r["value"] is not None]
        if not values:
            continue
        first, last = values[0], values[-1]
        change = last - first
        pct = (change / abs(first) * 100) if first else None
        entities = OrderedDict()
        for r in recs:
            if r["entity"]:
                entities.setdefault(r["entity"], []).append(r)
        entity_latest = {}
        for ent, erecs in entities.items():
            erecs.sort(key=lambda r: time_key(r["time"]))
            entity_latest[ent] = erecs[-1]["value"]
        first_time = recs[0]["time"] if recs[0]["time"] else None
        last_time = recs[-1]["time"] if recs[-1]["time"] else None
        analysis.append({
            "indicator": ind,
            "source": source,
            "n": len(recs),
            "first": first,
            "last": last,
            "change": change,
            "pct": pct,
            "min": min(values),
            "max": max(values),
            "mean": sum(values) / len(values),
            "entity_latest": entity_latest,
            "time_span": (first_time, last_time),
        })
    analysis.sort(key=lambda a: abs(a["pct"] or 0.0), reverse=True)
    return analysis


def trend_label(pct):
    if pct is None:
        return "stable"
    if pct >= 3:
        return "rising"
    if pct <= -3:
        return "falling"
    return "stable"


# ----------------------------------------------------------------------
# Formatting helpers
# ----------------------------------------------------------------------

def fmt(value, digits=2):
    if value is None:
        return "\u2014"
    return "{:,.{}f}".format(value, digits)


def span_text(a):
    t0, t1 = a["time_span"]
    if t0 and t1:
        return "{} \u2192 {}".format(t0, t1)
    return "observed window"


def hbar_range(value, vmin, vmax, width=18):
    if vmin == vmax:
        return "\u2591" * width
    frac = (value - vmin) / (vmax - vmin)
    frac = max(0.0, min(1.0, frac))
    filled = int(round(frac * width))
    return "\u2588" * filled + "\u2591" * (width - filled)


def md_table(headers, rows):
    out = ["| " + " | ".join(headers) + " |",
           "|" + "|".join(["---"] * len(headers)) + "|"]
    for row in rows:
        out.append("| " + " | ".join(str(c) for c in row) + " |")
    return "\n".join(out)


def indicator_label(a, multi):
    if multi:
        return "{} \u00b7 {}".format(a["indicator"], a["source"].stem)
    return a["indicator"]


# ----------------------------------------------------------------------
# Report
# ----------------------------------------------------------------------

def build_report(analysis, sources):
    out = []
    A = out.append
    multi = len({a["source"] for a in analysis}) > 1

    A("# European Economic Performance: A Data Story")
    A("")
    A("> **Audience:** decision-makers \u00b7 **Source:** local workspace dataset \u00b7 "
      "**Method:** trend & comparison analysis")
    A("")

    if not analysis:
        A("## The Hook")
        A("")
        A("The workspace does not contain a parseable European economic performance series, "
          "so this report cannot yet tell the story. The files inspected were:")
        A("")
        for s in sources:
            A("- `{}`".format(s.name))
        A("")
        A("**Next step:** add a tabular dataset (CSV/TSV/JSON) with a time column "
          "(e.g. year), numeric indicators (GDP, inflation, unemployment, growth), and "
          "optionally a country dimension, then re-run this analysis.")
        A("")
        A("## Appendix: Method")
        A("")
        A("Series are grouped by indicator, ordered by time, and measured as "
          "first-to-last change. Country comparisons use the latest observation per "
          "entity. Missing values are excluded; percentage changes are simple deltas.")
        return "\n".join(out)

    top = analysis[0]
    rising = [a for a in analysis if trend_label(a["pct"]) == "rising"]
    falling = [a for a in analysis if trend_label(a["pct"]) == "falling"]
    stable = [a for a in analysis if trend_label(a["pct"]) == "stable"]

    A("## The Hook")
    A("")
    A("One number dominates this dataset: **{}** moved **{}%** over the window "
      "({}). That is the strongest signal in the European economic picture these "
      "data describe \u2014 and it is the story this report unpacks.".format(
          indicator_label(top, multi), fmt(top["pct"], 1), span_text(top)))
    A("")
    A("At a glance: **{} indicator(s) rising**, **{} falling**, **{} stable**; "
      "**{} country/region comparison(s)** available.".format(
          len(rising), len(falling), len(stable),
          sum(1 for a in analysis if len(a["entity_latest"]) >= 2)))
    A("")

    A("## The Context: Where Europe Stands")
    A("")
    A("The baseline picture across the indicators in the dataset:")
    A("")
    rows = []
    for a in analysis[:12]:
        trend = "\u25b2 rising" if trend_label(a["pct"]) == "rising" else (
            "\u25bc falling" if trend_label(a["pct"]) == "falling" else "\u25cf stable")
        rows.append([indicator_label(a, multi), fmt(a["first"]), fmt(a["last"]),
                     fmt(a["change"]), fmt(a["pct"], 1) + "%", trend])
    A(md_table(["Indicator", "Earliest", "Latest", "\u0394", "\u0394%", "Trend"], rows))
    A("")

    A("## The Conflict: What the Data Reveals")
    A("")
    A("The European economy is not moving in one direction \u2014 it is diverging.")
    A("")
    if rising:
        A("**Heading up** (strongest positive moves):")
        A("")
        for a in rising[:5]:
            A("- **{}**: +{}% ({} \u2192 {})".format(
                indicator_label(a, multi), fmt(a["pct"], 1), fmt(a["first"]), fmt(a["last"])))
        A("")
    if falling:
        A("**Heading down** (largest declines):")
        A("")
        for a in falling[:5]:
            A("- **{}**: {}% ({} \u2192 {})".format(
                indicator_label(a, multi), fmt(a["pct"], 1), fmt(a["first"]), fmt(a["last"])))
        A("")
    if not rising and not falling:
        A("All observed indicators are broadly stable over the window.")
        A("")

    with_entities = [a for a in analysis if len(a["entity_latest"]) >= 2]
    if with_entities:
        A("## The Deep Dive: Comparing the Countries")
        A("")
        A("Where the data include a country/region dimension, the latest readings line up as follows:")
        A("")
        for a in with_entities[:4]:
            A("### {}".format(indicator_label(a, multi)))
            A("")
            items = sorted(a["entity_latest"].items(), key=lambda kv: kv[1], reverse=True)
            vals = [v for _, v in items]
            vmin, vmax = min(vals), max(vals)
            brows = []
            for ent, val in items[:8]:
                brows.append([ent, fmt(val), hbar_range(val, vmin, vmax)])
            A(md_table(["Country / region", "Latest value", "Relative position"], brows))
            A("")

    A("## The Insight")
    A("")
    A("The clearest insight from these data: **{}** moved {}% over the window \u2014 "
      "the largest shift in the dataset. Direction matters more than level: the story "
      "is not only where Europe stands today, but how quickly it is changing.".format(
          indicator_label(top, multi), fmt(top["pct"], 1)))
    A("")
    if rising and falling:
        A("The headline tension is between **{}** (up {}%) and **{}** (down {}%). "
          "A performance that is real but uneven: strength in some areas is not yet "
          "translating into broad-based gains.".format(
              indicator_label(rising[0], multi), fmt(rising[0]["pct"], 1),
              indicator_label(falling[0], multi), fmt(abs(falling[0]["pct"] or 0.0), 1)))
    elif rising:
        A("The momentum is broad and positive \u2014 led by {}, every moving indicator "
          "in this dataset is pointing up. The risk is complacency, not stagnation.".format(
              indicator_label(rising[0], multi)))
    elif falling:
        A("The pressure is broad and negative \u2014 led by {}, every moving indicator "
          "in this dataset is pointing down. This is an urgency signal, not a pause.".format(
              indicator_label(falling[0], multi)))
    A("")

    A("## The Resolution: What to Do About It")
    A("")
    A("Three actions follow directly from the data:")
    A("")
    focus_win = rising[0] if rising else top
    focus_loss = falling[0] if falling else top
    A("1. **Protect and extend the winner.** {} improved by {}% \u2014 double down on "
      "the policies, investments and segments behind it.".format(
          indicator_label(focus_win, multi), fmt(focus_win["pct"], 1)))
    A("2. **Fix the laggard.** {} declined by {}% \u2014 run a root-cause review now, "
      "before it drags on the rest of the economy.".format(
          indicator_label(focus_loss, multi), fmt(abs(focus_loss["pct"] or 0.0), 1)))
    A("3. **Re-balance the mix.** Review the divergence between the fastest and slowest "
      "series at least quarterly; a widening gap is the early-warning sign to act on.")
    A("")

    A("## The Call to Action")
    A("")
    A("- **Decide:** commission the deep-dive on **{}** within 30 days.".format(
        indicator_label(focus_loss, multi)))
    A("- **Track:** refresh this dataset quarterly and re-run the same story arc to "
      "measure whether the gap is closing.")
    A("- **Ask:** the data-backed request is to fund the fix for the lagging series \u2014 "
      "the payoff is the gap between its current trajectory and the leading series.")
    A("")

    A("## Appendix: Data & Method")
    A("")
    A("**Sources found and used in this workspace:**")
    A("")
    for s in sources:
        A("- `{}` ({} bytes)".format(s.name, s.stat().st_size))
    A("")
    A("**Method:** series were extracted from the tabular files above; indicators were "
      "grouped, ordered by time, and measured as first-to-last change. Country/region "
      "comparisons use the latest available observation per entity. Bars show relative "
      "position within each series.")
    A("")
    A("**Caveats:** sample sizes and time coverage vary by series; missing values were "
      "excluded; percentage changes are simple first-to-last deltas and may mask "
      "intermediate volatility. Correlation in this report does not establish causation.")
    return "\n".join(out)


# ----------------------------------------------------------------------
# Main
# ----------------------------------------------------------------------

def main():
    print("Workspace:", WORKSPACE)
    files = discover_data_files()
    print("Candidate files:", [f.name for f in files])

    analysis = []
    sources = []
    for path in files:
        rows = load_rows(path)
        if not rows:
            print("  no rows from", path.name)
            continue
        schema = identify_columns(rows)
        if not schema:
            print("  no schema from", path.name)
            continue
        records = extract_records(rows, schema)
        if not records:
            print("  no numeric records from", path.name)
            continue
        grouped = analyze_groups(records, path)
        if not grouped:
            print("  no indicators from", path.name)
            continue
        print("  parsed {}: {} records, {} indicators".format(
            path.name, len(records), len(grouped)))
        analysis.extend(grouped)
        sources.append(path)

    report = build_report(analysis, sources)

    if len(sys.argv) > 1:
        output = Path(sys.argv[1])
        if not output.is_absolute():
            output = WORKSPACE / output
    else:
        output = DEFAULT_OUTPUT

    output.write_text(report, encoding="utf-8")
    print("Report written to:", output)
    print("Indicators analyzed:", [a["indicator"] for a in analysis[:10]])
    print("---")
    for a in analysis:
        print("  {:<28} first={:<12} last={:<12} pct={}".format(
            a["indicator"], fmt(a["first"]), fmt(a["last"]),
            "n/a" if a["pct"] is None else fmt(a["pct"], 1) + "%"))


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Task-scoped helper: build a data storytelling report from the European
economic performance data found in this workspace directory at runtime.
Output: europe_economic_performance_story.md (Markdown report)."""

import csv, json, math, statistics, sys
from pathlib import Path

WORKSPACE = Path(__file__).resolve().parent
OUTPUT_PATH = WORKSPACE / "europe_economic_performance_story.md"

EU_WORDS = ["euro", "europe", "eurozone", "eu_", "eu-", "gdp", "economy",
            "economic", "inflation", "unemployment", "debt", "growth",
            "per capita", "export", "import", "country", "countries", "nation"]
ENTITY_HINTS = ["country", "nation", "state", "region", "entity", "economy"]
TIME_HINTS = ["year", "quarter", "period", "date", "time", "month"]


def num(v):
    """Coerce to float or None."""
    if v is None or isinstance(v, bool):
        return None
    if isinstance(v, (int, float)):
        return float(v)
    s = str(v).strip().rstrip("%").replace(",", "").strip()
    try:
        f = float(s)
        return f if math.isfinite(f) else None
    except ValueError:
        return None


def is_num(v):
    return num(v) is not None


def fmt(v, d=2):
    if v is None:
        return "n/a"
    f = float(v)
    if abs(f - round(f)) < 1e-9 and abs(f) < 1e15:
        return f"{int(round(f)):,}"
    return f"{f:,.{d}f}"


def norm(k):
    return str(k).strip().lower().replace("_", " ").replace("-", " ")


def parse_json(path):
    try:
        with open(path, encoding="utf-8-sig", errors="replace") as fh:
            data = json.load(fh)
    except Exception:
        return []
    rows = []
    if isinstance(data, list):
        rows = [r for r in data if isinstance(r, dict)]
    elif isinstance(data, dict):
        for v in data.values():
            if isinstance(v, list) and v and isinstance(v[0], dict):
                rows = [r for r in v if isinstance(r, dict)]
                break
        else:
            keys = [k for k, v in data.items() if isinstance(v, list)]
            if keys:
                n = max(len(data[k]) for k in keys)
                rows = [{k: (data[k][i] if i < len(data[k]) else None) for k in data} for i in range(n)]
            else:
                rows = [data]
    return [{norm(k): v for k, v in r.items() if k is not None} for r in rows]


def parse_csv(path):
    try:
        with open(path, encoding="utf-8-sig", errors="replace", newline="") as fh:
            sample = fh.read(8192)
            fh.seek(0)
            try:
                dialect = csv.Sniffer().sniff(sample, delimiters=",;\t|")
            except csv.Error:
                dialect = csv.excel
            reader = csv.DictReader(fh, dialect=dialect)
            if reader.fieldnames is None:
                return []
            rows = [r for r in reader if any(str(v).strip() != "" for v in r.values())]
    except Exception:
        return []
    return [{norm(k): v for k, v in r.items() if k is not None} for r in rows]


def parse_text(path):
    try:
        with open(path, encoding="utf-8-sig", errors="replace") as fh:
            lines = [ln.strip() for ln in fh if ln.strip()]
    except Exception:
        return []
    recs, cur = [], {}
    for ln in lines:
        if ":" in ln:
            k, _, v = ln.partition(":")
            k = norm(k)
            if k:
                cur[k] = v.strip()
        elif cur:
            recs.append(cur)
            cur = {}
    if cur:
        recs.append(cur)
    return recs


def discover():
    found = []
    for path in sorted(WORKSPACE.iterdir()):
        if not path.is_file() or path.name in {Path(__file__).name, OUTPUT_PATH.name}:
            continue
        if path.suffix.lower() not in {".csv", ".tsv", ".tab", ".txt", ".json", ".jsonl"}:
            continue
        rows = parse_json(path) if path.suffix.lower() in {".json", ".jsonl"} else []
        if not rows and path.suffix.lower() in {".csv", ".tsv", ".tab", ".txt"}:
            rows = parse_csv(path)
        if not rows and path.suffix.lower() == ".txt":
            rows = parse_text(path)
        if not rows:
            continue
        cols = {}
        for r in rows:
            for k, v in r.items():
                cols.setdefault(k, []).append(v)
        numcols = [k for k, vals in cols.items() if any(is_num(v) for v in vals)]
        if not numcols:
            continue
        name = path.name.lower()
        text = name + "\n" + "\n".join(" ".join(str(v) for v in r.values()) for r in rows[:30])
        low = text.lower()
        eu = any(w in name for w in EU_WORDS) or sum(1 for w in EU_WORDS if w in low) >= 2
        found.append({"path": path, "rows": rows, "numcols": numcols, "eu": eu})
    return found


def pick_primary(found):
    if not found:
        return None
    return max(found, key=lambda f: (1000 if f["eu"] else 0) + 10 * len(f["numcols"]) + min(len(f["rows"]), 5000))


def classify(ds):
    cols = ds["numcols"]
    numeric = set(cols)
    entity_col = time_col = None
    for c in ds["rows"][0].keys():
        low = c.lower()
        if c in numeric:
            continue
        if entity_col is None and any(h in low for h in ENTITY_HINTS):
            entity_col = c
        elif time_col is None and any(h in low for h in TIME_HINTS):
            time_col = c
    metrics = [c for c in cols if c != entity_col and c != time_col]
    return entity_col, time_col, metrics


def series(rows, tcol, m):
    s = []
    for r in rows:
        v = num(r.get(m))
        if v is None:
            continue
        t = r.get(tcol) if tcol else None
        s.append((t, v))
    if tcol:
        def key(item):
            t = item[0]
            try:
                return (0, float(t))
            except (TypeError, ValueError):
                return (1, str(t))
        s.sort(key=key)
    return s


def latest_per_entity(rows, ecol, m, tcol):
    out = {}
    for r in rows:
        e = r.get(ecol)
        v = num(r.get(m))
        if e is None or v is None or not str(e).strip():
            continue
        t = r.get(tcol) if tcol else None
        k = str(e).strip()
        if k not in out:
            out[k] = (t, v)
            continue
        pt, pv = out[k]
        try:
            if t is not None and pt is not None and float(t) >= float(pt):
                out[k] = (t, v)
        except (TypeError, ValueError):
            pass
    return out


def stats_for(rows, ecol, tcol, metrics):
    st = {}
    for m in metrics:
        s = series(rows, tcol, m)
        if len(s) < 2:
            continue
        first, last = s[0][1], s[-1][1]
        pct = ((last - first) / abs(first) * 100.0) if first else None
        ents = latest_per_entity(rows, ecol, m, tcol) if ecol else {}
        st[m] = {"first": first, "last": last, "change": last - first,
                 "pct": pct, "n": len(s), "entities": ents}
    return st


def headline(st):
    cands = []
    for m, s in st.items():
        if len(s["entities"]) >= 2:
            vals = [v for _, v in s["entities"].values()]
            cands.append((max(vals) - min(vals), abs(s["pct"] or 0.0), m))
    if cands:
        return max(cands, key=lambda x: (x[0], x[1]))[2]
    tc = [(abs(s["pct"]), m) for m, s in st.items() if s["pct"] is not None]
    return max(tc)[1] if tc else None


def fastest(st):
    tc = [(abs(s["pct"]), m) for m, s in st.items() if s["pct"] is not None]
    return max(tc)[1] if tc else None


def span(rows, tcol):
    if not tcol:
        return None
    ts = [str(r.get(tcol)).strip() for r in rows if r.get(tcol) is not None and str(r.get(tcol)).strip()]
    if not ts:
        return None
    def key(t):
        try:
            return (0, float(t))
        except ValueError:
            return (1, t)
    return sorted(ts, key=key)[0], sorted(ts, key=key)[-1]


def barchart(labels, values, width=26):
    pairs = sorted(zip(labels, values), key=lambda x: x[1], reverse=True)
    lo, hi = min(values), max(values)
    d = hi - lo
    out = []
    for label, v in pairs:
        n = 1 if d == 0 else max(1, int(round((v - lo) / d * (width - 2))) + 1)
        out.append(f"  {str(label)[:22]:<22} |{'#' * n:<{width}}| {fmt(v)}")
    return "\n".join(out)


def appendix(primary, found):
    L = ["## Appendix — Data & Method", ""]
    L.append("| File | Rows | Numeric columns | Europe match |")
    L.append("|---|---|---|---|")
    for f in found:
        L.append(f"| {f['path'].name} | {len(f['rows'])} | {', '.join(f['numcols'])} | {'yes' if f['eu'] else 'no'} |")
    L.append("")
    L.append(f"**Primary dataset used:** `{primary['path'].name}` (highest Europe-relevance score, then row count and indicator count).")
    L.append("")
    L.append("**Limitations:** values are the latest observation per economy; indicator sample sizes are in the trend table; divergence shows correlation, not causation — recommendations are hypotheses to validate.")
    L.append("")
    L.append("_Generated by the task-scoped report builder from files found in the workspace directory._")
    return "\n".join(L)


def empty_report(found):
    L = ["# European Economic Performance — Data Storytelling Report", "",
         "## The Hook", "",
         "**No European economic performance dataset was located in this directory**, so no numeric story can be told from it yet.", ""]
    if found:
        L.append("## Files found (not matching European economic keywords)")
        L.append("")
        L.append("| File | Rows | Numeric columns |")
        L.append("|---|---|---|")
        for f in found:
            L.append(f"| {f['path'].name} | {len(f['rows'])} | {', '.join(f['numcols'])} |")
    else:
        L.append("No CSV / TSV / TXT / JSON / JSONL data files with numeric columns were found.")
    L.append("")
    L.append("## Next step")
    L.append("")
    L.append("Add a plain-text dataset with columns such as `Country`, `Year`, and indicators (GDP, growth, inflation, unemployment, debt), then re-run the report builder.")
    L.append("")
    L.append("## Call to action")
    L.append("")
    L.append("Choose the indicator that matters for the decision and ensure the data covers at least two time periods and several economies so a comparison story can be built.")
    L.append("")
    L.append("_No numeric European economic data was available at generation time._")
    return "\n".join(L)


def build_story(primary, found):
    rows = primary["rows"]
    ecol, tcol, metrics = classify(primary)
    st = stats_for(rows, ecol, tcol, metrics)
    h = headline(st)
    f = fastest(st)

    if h is None or not st:
        L = ["# European Economic Performance — Data Storytelling Report", "",
             "## The data", "",
             f"The primary dataset (`{primary['path'].name}`) has **{len(rows)} rows**; numeric columns: {', '.join(primary['numcols'])}.", "",
             "Not enough structure was detected (at least two observations per indicator) for a trend or comparison narrative.", "", appendix(primary, found)]
        return "\n".join(L)

    s = st[h]
    ents = s["entities"]
    vals = [v for _, v in ents.values()]
    top = max(ents, key=lambda k: ents[k][1])
    bot = min(ents, key=lambda k: ents[k][1])
    tv, bv = ents[top][1], ents[bot][1]
    gap = tv - bv
    gap_pct = (gap / abs(bv) * 100.0) if bv else None
    med = statistics.median(vals)
    below = sum(1 for v in vals if v <= med)
    below_share = below / len(vals) * 100.0
    top_med = (tv - med) / abs(med) * 100.0 if med else None
    bot_med = (bv - med) / abs(med) * 100.0 if med else None
    fpct = st[f]["pct"]
    sp = span(rows, tcol)
    n_ent = len(ents)

    L = []
    L.append("# European Economic Performance — Data Storytelling Report")
    L.append("")
    L.append("## The Hook")
    L.append("")
    if n_ent >= 2:
        L.append(f"European economic performance is **not one story but a split screen**: in the latest period, **{top}** posted **{fmt(tv)}** on *{h}* while **{bot}** sat at **{fmt(bv)}** — a gap of **{fmt(gap)} ({fmt(gap_pct, 1)}%)** across the {n_ent} economies covered.")
    else:
        L.append(f"The headline number for *{h}* moved from **{fmt(s['first'])}** to **{fmt(s['last'])}** ({fmt(s['pct'], 1)}%) over the observation period.")
    L.append("")
    L.append("## The Context")
    L.append("")
    ctx = f"The picture is built from **{len(rows)} data points**"
    if sp:
        ctx += f" spanning **{sp[0]} → {sp[1]}**"
    if n_ent:
        ctx += f" across **{n_ent} European economies**"
    L.append(ctx + ".")
    L.append("")
    if med is not None and n_ent >= 2:
        L.append(f"The median value of *{h}* is **{fmt(med)}**, so the leader runs **{fmt(top_med, 1)}% above** the typical economy while the laggard sits **{fmt(bot_med, 1)}% below** it — the baseline is not a plateau, it is a slope.")
        L.append("")
    L.append("## The Conflict")
    L.append("")
    if n_ent >= 2:
        L.append(f"The headline hides a structural problem: **{below} of {n_ent} economies ({fmt(below_share, 0)}%)** sit at or below the median on *{h}*. The fastest-moving metric in the dataset is *{f}*, which swung **{fmt(fpct, 1)}%** over the period — an early-warning signal that the gap may widen before it narrows.")
    else:
        L.append(f"The tension in this dataset is momentum: *{f}* moved **{fmt(fpct, 1)}%** over the period, the largest swing of any tracked indicator.")
    L.append("")
    L.append("## The Insight")
    L.append("")
    L.append(f"### Where the economies stand (latest period, *{h}*)")
    L.append("")
    L.append("```")
    L.append(barchart(list(ents.keys()), vals))
    L.append("```")
    L.append("")
    L.append("### Ranking table")
    L.append("")
    L.append("| Rank | Economy | Value |")
    L.append("|---|---|---|")
    for i, (name, (_t, v)) in enumerate(sorted(ents.items(), key=lambda kv: kv[1][1], reverse=True), start=1):
        L.append(f"| {i} | {name} | {fmt(v)} |")
    L.append("")
    L.append("### How the indicators moved over the period")
    L.append("")
    L.append("| Indicator | First | Latest | Change | % Change | Observations |")
    L.append("|---|---|---|---|---|---|")
    for m, x in sorted(st.items(), key=lambda kv: abs(kv[1]["pct"] or 0.0), reverse=True):
        L.append(f"| {m} | {fmt(x['first'])} | {fmt(x['last'])} | {fmt(x['change'])} | {fmt(x['pct'], 1)}% | {x['n']} |")
    L.append("")
    L.append(f"**Read the pattern:** the widest divergence sits on *{h}*; the momentum leader is *{f}*. Together they define the narrative: where you stand on {h} today, and which way {f} is pulling you.")
    L.append("")
    L.append("## The Recommendation")
    L.append("")
    L.append("Three levers follow directly from the data:")
    L.append("")
    if n_ent >= 2:
        L.append(f"1. **Learn from the leader.** {top} holds a {fmt(top_med, 1)}% edge over the median on *{h}* ({fmt(tv)} vs. {fmt(med)}). Investigate which policies, endowments, or exposures explain that lead and test them where the gap is widest ({bot} and peers).")
    L.append(f"2. **Manage the fastest-moving metric.** *{f}* changed by {fmt(fpct, 1)}% across the period. Track it monthly rather than quarterly and set a trigger threshold before the swing compounds.")
    if n_ent >= 2:
        L.append(f"3. **Raise the floor, not just the ceiling.** {below} of {n_ent} economies trail the median; set {fmt(med)} on *{h}* as the near-term benchmark for the laggards.")
    L.append("")
    L.append("### Expected impact")
    L.append("")
    half = (tv - med) / 2
    L.append(f"- **Leader replication** converts the leader's edge into a template: closing half the gap between median and leader lifts the median by **{fmt(half)} points** (from {fmt(med)} to {fmt(med + half)}).")
    L.append(f"- **Early-warning tracking** on *{f}* buys a quarter of reaction time before the divergence widens further.")
    L.append("- **Benchmarking laggards** at the median is measurable, credible, and within reach of existing data collection.")
    L.append("")
    L.append("## Call to Action")
    L.append("")
    L.append("**The ask:** pick one of the three levers above to fund this quarter — leader replication, early-warning tracking, or laggard uplift — and commission a monthly follow-up on this same dataset so the narrative is re-tested against new observations. The data has told us where the story is; the decision is which chapter to write next.")
    L.append("")
    L.append("---")
    L.append("")
    L.append(appendix(primary, found))
    return "\n".join(L)


def main():
    argv = [a for a in sys.argv[1:] if a]
    mode = argv[0] if argv else "generate"
    if mode != "generate":
        print(f"Unknown mode: {mode}", file=sys.stderr)
        return 2
    found = discover()
    primary = pick_primary(found)
    report = build_story(primary, found) if primary else empty_report(found)
    OUTPUT_PATH.write_text(report, encoding="utf-8")

    print("FOUND DATA FILES:")
    for f in found:
        print(f"  - {f['path'].name} (rows={len(f['rows'])}, numeric={len(f['numcols'])}, europe_match={f['eu']})")
    if not found:
        print("  (none)")
    if primary:
        ecol, tcol, metrics = classify(primary)
        st = stats_for(primary["rows"], ecol, tcol, metrics)
        print(f"PRIMARY DATASET : {primary['path'].name}")
        print(f"HEADLINE METRIC : {headline(st)}")
        print(f"FASTEST METRIC  : {fastest(st)}")
        print(f"TIME SPAN       : {span(primary['rows'], tcol)}")
    print(f"REPORT WRITTEN  : {OUTPUT_PATH}")
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Task-scoped helper: build a data storytelling report from the European
economic performance data found in this workspace directory at runtime.
Output: europe_economic_performance_story.md (Markdown report).

Trusted task: Create a data storytelling report based on the data about the
European economic performance in this directory."""

import csv, json, math, statistics, sys
from pathlib import Path

WORKSPACE = Path(__file__).resolve().parent
OUTPUT_PATH = WORKSPACE / "europe_economic_performance_story.md"

EU_WORDS = ["euro", "europe", "eurozone", "eu_", "eu-", "gdp", "economy",
            "economic", "inflation", "unemployment", "debt", "growth",
            "per capita", "export", "import", "country", "countries", "nation"]
ENTITY_HINTS = ["country", "nation", "state", "region", "entity", "economy"]
TIME_HINTS = ["year", "quarter", "period", "date", "time", "month"]


def num(v):
    """Coerce to float or None."""
    if v is None or isinstance(v, bool):
        return None
    if isinstance(v, (int, float)):
        return float(v)
    s = str(v).strip().rstrip("%").replace(",", "").strip()
    try:
        f = float(s)
        return f if math.isfinite(f) else None
    except ValueError:
        return None


def is_num(v):
    return num(v) is not None


def fmt(v, d=2):
    if v is None:
        return "n/a"
    f = float(v)
    if abs(f - round(f)) < 1e-9 and abs(f) < 1e15:
        return f"{int(round(f)):,}"
    return f"{f:,.{d}f}"


def norm(k):
    return str(k).strip().lower().replace("_", " ").replace("-", " ")


def parse_json(path):
    try:
        with open(path, encoding="utf-8-sig", errors="replace") as fh:
            data = json.load(fh)
    except Exception:
        return []
    rows = []
    if isinstance(data, list):
        rows = [r for r in data if isinstance(r, dict)]
    elif isinstance(data, dict):
        for v in data.values():
            if isinstance(v, list) and v and isinstance(v[0], dict):
                rows = [r for r in v if isinstance(r, dict)]
                break
        else:
            keys = [k for k, v in data.items() if isinstance(v, list)]
            if keys:
                n = max(len(data[k]) for k in keys)
                rows = [{k: (data[k][i] if i < len(data[k]) else None) for k in data} for i in range(n)]
            else:
                rows = [data]
    return [{norm(k): v for k, v in r.items() if k is not None} for r in rows]


def parse_csv(path):
    try:
        with open(path, encoding="utf-8-sig", errors="replace", newline="") as fh:
            sample = fh.read(8192)
            fh.seek(0)
            try:
                dialect = csv.Sniffer().sniff(sample, delimiters=",;\t|")
            except csv.Error:
                dialect = csv.excel
            reader = csv.DictReader(fh, dialect=dialect)
            if reader.fieldnames is None:
                return []
            rows = [r for r in reader if any(str(v).strip() != "" for v in r.values())]
    except Exception:
        return []
    return [{norm(k): v for k, v in r.items() if k is not None} for r in rows]


def parse_text(path):
    try:
        with open(path, encoding="utf-8-sig", errors="replace") as fh:
            lines = [ln.strip() for ln in fh if ln.strip()]
    except Exception:
        return []
    recs, cur = [], {}
    for ln in lines:
        if ":" in ln:
            k, _, v = ln.partition(":")
            k = norm(k)
            if k:
                cur[k] = v.strip()
        elif cur:
            recs.append(cur)
            cur = {}
    if cur:
        recs.append(cur)
    return recs


def discover():
    found = []
    for path in sorted(WORKSPACE.iterdir()):
        if not path.is_file() or path.name in {Path(__file__).name, OUTPUT_PATH.name}:
            continue
        if path.suffix.lower() not in {".csv", ".tsv", ".tab", ".txt", ".json", ".jsonl"}:
            continue
        rows = parse_json(path) if path.suffix.lower() in {".json", ".jsonl"} else []
        if not rows and path.suffix.lower() in {".csv", ".tsv", ".tab", ".txt"}:
            rows = parse_csv(path)
        if not rows and path.suffix.lower() == ".txt":
            rows = parse_text(path)
        if not rows:
            continue
        cols = {}
        for r in rows:
            for k, v in r.items():
                cols.setdefault(k, []).append(v)
        numcols = [k for k, vals in cols.items() if any(is_num(v) for v in vals)]
        if not numcols:
            continue
        name = path.name.lower()
        text = name + "\n" + "\n".join(" ".join(str(v) for v in r.values()) for r in rows[:30])
        low = text.lower()
        eu = any(w in name for w in EU_WORDS) or sum(1 for w in EU_WORDS if w in low) >= 2
        found.append({"path": path, "rows": rows, "numcols": numcols, "eu": eu})
    return found


def pick_primary(found):
    if not found:
        return None
    return max(found, key=lambda f: (1000 if f["eu"] else 0) + 10 * len(f["numcols"]) + min(len(f["rows"]), 5000))


def classify(ds):
    cols = ds["numcols"]
    numeric = set(cols)
    entity_col = time_col = None
    for c in ds["rows"][0].keys():
        low = c.lower()
        if c in numeric:
            continue
        if entity_col is None and any(h in low for h in ENTITY_HINTS):
            entity_col = c
        elif time_col is None and any(h in low for h in TIME_HINTS):
            time_col = c
    metrics = [c for c in cols if c != entity_col and c != time_col]
    return entity_col, time_col, metrics


def series(rows, tcol, m):
    s = []
    for r in rows:
        v = num(r.get(m))
        if v is None:
            continue
        t = r.get(tcol) if tcol else None
        s.append((t, v))
    if tcol:
        def key(item):
            t = item[0]
            try:
                return (0, float(t))
            except (TypeError, ValueError):
                return (1, str(t))
        s.sort(key=key)
    return s


def latest_per_entity(rows, ecol, m, tcol):
    out = {}
    for r in rows:
        e = r.get(ecol)
        v = num(r.get(m))
        if e is None or v is None or not str(e).strip():
            continue
        t = r.get(tcol) if tcol else None
        k = str(e).strip()
        if k not in out:
            out[k] = (t, v)
            continue
        pt, pv = out[k]
        try:
            if t is not None and pt is not None and float(t) >= float(pt):
                out[k] = (t, v)
        except (TypeError, ValueError):
            pass
    return out


def stats_for(rows, ecol, tcol, metrics):
    st = {}
    for m in metrics:
        s = series(rows, tcol, m)
        if len(s) < 2:
            continue
        first, last = s[0][1], s[-1][1]
        pct = ((last - first) / abs(first) * 100.0) if first else None
        ents = latest_per_entity(rows, ecol, m, tcol) if ecol else {}
        st[m] = {"first": first, "last": last, "change": last - first,
                 "pct": pct, "n": len(s), "entities": ents}
    return st


def headline(st):
    cands = []
    for m, s in st.items():
        if len(s["entities"]) >= 2:
            vals = [v for _, v in s["entities"].values()]
            cands.append((max(vals) - min(vals), abs(s["pct"] or 0.0), m))
    if cands:
        return max(cands, key=lambda x: (x[0], x[1]))[2]
    tc = [(abs(s["pct"]), m) for m, s in st.items() if s["pct"] is not None]
    return max(tc)[1] if tc else None


def fastest(st):
    tc = [(abs(s["pct"]), m) for m, s in st.items() if s["pct"] is not None]
    return max(tc)[1] if tc else None


def span(rows, tcol):
    if not tcol:
        return None
    ts = [str(r.get(tcol)).strip() for r in rows if r.get(tcol) is not None and str(r.get(tcol)).strip()]
    if not ts:
        return None
    def key(t):
        try:
            return (0, float(t))
        except ValueError:
            return (1, t)
    return sorted(ts, key=key)[0], sorted(ts, key=key)[-1]


def barchart(labels, values, width=26):
    pairs = sorted(zip(labels, values), key=lambda x: x[1], reverse=True)
    lo, hi = min(values), max(values)
    d = hi - lo
    out = []
    for label, v in pairs:
        n = 1 if d == 0 else max(1, int(round((v - lo) / d * (width - 2))) + 1)
        out.append(f"  {str(label)[:22]:<22} |{'#' * n:<{width}}| {fmt(v)}")
    return "\n".join(out)


def appendix(primary, found):
    L = ["## Appendix — Data & Method", ""]
    L.append("| File | Rows | Numeric columns | Europe match |")
    L.append("|---|---|---|---|")
    for f in found:
        L.append(f"| {f['path'].name} | {len(f['rows'])} | {', '.join(f['numcols'])} | {'yes' if f['eu'] else 'no'} |")
    L.append("")
    L.append(f"**Primary dataset used:** `{primary['path'].name}` (highest Europe-relevance score, then row count and indicator count).")
    L.append("")
    L.append("**Limitations:** values are the latest observation per economy; indicator sample sizes are in the trend table; divergence shows correlation, not causation — recommendations are hypotheses to validate.")
    L.append("")
    L.append("_Generated by the task-scoped report builder from files found in the workspace directory._")
    return "\n".join(L)


def empty_report(found):
    L = ["# European Economic Performance — Data Storytelling Report", "",
         "## The Hook", "",
         "**No European economic performance dataset was located in this directory**, so no numeric story can be told from it yet.", ""]
    if found:
        L.append("## Files found (not matching European economic keywords)")
        L.append("")
        L.append("| File | Rows | Numeric columns |")
        L.append("|---|---|---|")
        for f in found:
            L.append(f"| {f['path'].name} | {len(f['rows'])} | {', '.join(f['numcols'])} |")
    else:
        L.append("No CSV / TSV / TXT / JSON / JSONL data files with numeric columns were found.")
    L.append("")
    L.append("## Next step")
    L.append("")
    L.append("Add a plain-text dataset with columns such as `Country`, `Year`, and indicators (GDP, growth, inflation, unemployment, debt), then re-run the report builder.")
    L.append("")
    L.append("## Call to action")
    L.append("")
    L.append("Choose the indicator that matters for the decision and ensure the data covers at least two time periods and several economies so a comparison story can be built.")
    L.append("")
    L.append("_No numeric European economic data was available at generation time._")
    return "\n".join(L)


def build_story(primary, found):
    rows = primary["rows"]
    ecol, tcol, metrics = classify(primary)
    st = stats_for(rows, ecol, tcol, metrics)
    h = headline(st)
    f = fastest(st)

    if h is None or not st:
        L = ["# European Economic Performance — Data Storytelling Report", "",
             "## The data", "",
             f"The primary dataset (`{primary['path'].name}`) has **{len(rows)} rows**; numeric columns: {', '.join(primary['numcols'])}.", "",
             "Not enough structure was detected (at least two observations per indicator) for a trend or comparison narrative.", "", appendix(primary, found)]
        return "\n".join(L)

    s = st[h]
    ents = s["entities"]
    vals = [v for _, v in ents.values()]
    top = max(ents, key=lambda k: ents[k][1])
    bot = min(ents, key=lambda k: ents[k][1])
    tv, bv = ents[top][1], ents[bot][1]
    gap = tv - bv
    gap_pct = (gap / abs(bv) * 100.0) if bv else None
    med = statistics.median(vals)
    below = sum(1 for v in vals if v <= med)
    below_share = below / len(vals) * 100.0
    top_med = (tv - med) / abs(med) * 100.0 if med else None
    bot_med = (bv - med) / abs(med) * 100.0 if med else None
    fpct = st[f]["pct"]
    sp = span(rows, tcol)
    n_ent = len(ents)

    L = []
    L.append("# European Economic Performance — Data Storytelling Report")
    L.append("")
    L.append("## The Hook")
    L.append("")
    if n_ent >= 2:
        L.append(f"European economic performance is **not one story but a split screen**: in the latest period, **{top}** posted **{fmt(tv)}** on *{h}* while **{bot}** sat at **{fmt(bv)}** — a gap of **{fmt(gap)} ({fmt(gap_pct, 1)}%)** across the {n_ent} economies covered.")
    else:
        L.append(f"The headline number for *{h}* moved from **{fmt(s['first'])}** to **{fmt(s['last'])}** ({fmt(s['pct'], 1)}%) over the observation period.")
    L.append("")
    L.append("## The Context")
    L.append("")
    ctx = f"The picture is built from **{len(rows)} data points**"
    if sp:
        ctx += f" spanning **{sp[0]} → {sp[1]}**"
    if n_ent:
        ctx += f" across **{n_ent} European economies**"
    L.append(ctx + ".")
    L.append("")
    if med is not None and n_ent >= 2:
        L.append(f"The median value of *{h}* is **{fmt(med)}**, so the leader runs **{fmt(top_med, 1)}% above** the typical economy while the laggard sits **{fmt(bot_med, 1)}% below** it — the baseline is not a plateau, it is a slope.")
        L.append("")
    L.append("## The Conflict")
    L.append("")
    if n_ent >= 2:
        L.append(f"The headline hides a structural problem: **{below} of {n_ent} economies ({fmt(below_share, 0)}%)** sit at or below the median on *{h}*. The fastest-moving metric in the dataset is *{f}*, which swung **{fmt(fpct, 1)}%** over the period — an early-warning signal that the gap may widen before it narrows.")
    else:
        L.append(f"The tension in this dataset is momentum: *{f}* moved **{fmt(fpct, 1)}%** over the period, the largest swing of any tracked indicator.")
    L.append("")
    L.append("## The Insight")
    L.append("")
    L.append(f"### Where the economies stand (latest period, *{h}*)")
    L.append("")
    L.append("```")
    L.append(barchart(list(ents.keys()), vals))
    L.append("```")
    L.append("")
    L.append("### Ranking table")
    L.append("")
    L.append("| Rank | Economy | Value |")
    L.append("|---|---|---|")
    for i, (name, (_t, v)) in enumerate(sorted(ents.items(), key=lambda kv: kv[1][1], reverse=True), start=1):
        L.append(f"| {i} | {name} | {fmt(v)} |")
    L.append("")
    L.append("### How the indicators moved over the period")
    L.append("")
    L.append("| Indicator | First | Latest | Change | % Change | Observations |")
    L.append("|---|---|---|---|---|---|")
    for m, x in sorted(st.items(), key=lambda kv: abs(kv[1]["pct"] or 0.0), reverse=True):
        L.append(f"| {m} | {fmt(x['first'])} | {fmt(x['last'])} | {fmt(x['change'])} | {fmt(x['pct'], 1)}% | {x['n']} |")
    L.append("")
    L.append(f"**Read the pattern:** the widest divergence sits on *{h}*; the momentum leader is *{f}*. Together they define the narrative: where you stand on {h} today, and which way {f} is pulling you.")
    L.append("")
    L.append("## The Recommendation")
    L.append("")
    L.append("Three levers follow directly from the data:")
    L.append("")
    if n_ent >= 2:
        L.append(f"1. **Learn from the leader.** {top} holds a {fmt(top_med, 1)}% edge over the median on *{h}* ({fmt(tv)} vs. {fmt(med)}). Investigate which policies, endowments, or exposures explain that lead and test them where the gap is widest ({bot} and peers).")
    L.append(f"2. **Manage the fastest-moving metric.** *{f}* changed by {fmt(fpct, 1)}% across the period. Track it monthly rather than quarterly and set a trigger threshold before the swing compounds.")
    if n_ent >= 2:
        L.append(f"3. **Raise the floor, not just the ceiling.** {below} of {n_ent} economies trail the median; set {fmt(med)} on *{h}* as the near-term benchmark for the laggards.")
    L.append("")
    L.append("### Expected impact")
    L.append("")
    half = (tv - med) / 2
    L.append(f"- **Leader replication** converts the leader's edge into a template: closing half the gap between median and leader lifts the median by **{fmt(half)} points** (from {fmt(med)} to {fmt(med + half)}).")
    L.append(f"- **Early-warning tracking** on *{f}* buys a quarter of reaction time before the divergence widens further.")
    L.append("- **Benchmarking laggards** at the median is measurable, credible, and within reach of existing data collection.")
    L.append("")
    L.append("## Call to Action")
    L.append("")
    L.append("**The ask:** pick one of the three levers above to fund this quarter — leader replication, early-warning tracking, or laggard uplift — and commission a monthly follow-up on this same dataset so the narrative is re-tested against new observations. The data has told us where the story is; the decision is which chapter to write next.")
    L.append("")
    L.append("---")
    L.append("")
    L.append(appendix(primary, found))
    return "\n".join(L)


def main():
    argv = [a for a in sys.argv[1:] if a]
    mode = argv[0] if argv else "create"
    allowed = {"create", "generate", "build"}
    if mode not in allowed:
        print(f"Unknown mode: {mode}", file=sys.stderr)
        return 2
    if len(argv) > 1:
        global OUTPUT_PATH
        OUTPUT_PATH = WORKSPACE / argv[1]
    found = discover()
    primary = pick_primary(found)
    report = build_story(primary, found) if primary else empty_report(found)
    OUTPUT_PATH.write_text(report, encoding="utf-8")

    print("FOUND DATA FILES:")
    for f in found:
        print(f"  - {f['path'].name} (rows={len(f['rows'])}, numeric={len(f['numcols'])}, europe_match={f['eu']})")
    if not found:
        print("  (none)")
    if primary:
        ecol, tcol, metrics = classify(primary)
        st = stats_for(primary["rows"], ecol, tcol, metrics)
        print(f"PRIMARY DATASET : {primary['path'].name}")
        print(f"HEADLINE METRIC : {headline(st)}")
        print(f"FASTEST METRIC  : {fastest(st)}")
        print(f"TIME SPAN       : {span(primary['rows'], tcol)}")
    print(f"REPORT WRITTEN  : {OUTPUT_PATH}")
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Compact task-scoped helper: create a data storytelling report from the
European economic performance data in this workspace directory (runtime
discovery), written to europe_economic_performance_story.md."""

import csv, json, math, statistics, sys
from pathlib import Path

WS = Path(__file__).resolve().parent
OUT = WS / "europe_economic_performance_story.md"
EU = ["euro", "europe", "eurozone", "eu", "gdp", "economy", "economic",
      "inflation", "unemployment", "debt", "growth", "per capita",
      "export", "import", "country", "countries", "nation"]


def nf(v):
    if v is None or isinstance(v, bool):
        return None
    if isinstance(v, (int, float)):
        return float(v)
    s = str(v).strip().rstrip("%").replace(",", "").strip()
    try:
        f = float(s)
        return f if math.isfinite(f) else None
    except ValueError:
        return None


def fm(v, d=2):
    if v is None:
        return "n/a"
    f = float(v)
    if abs(f - round(f)) < 1e-9 and abs(f) < 1e15:
        return f"{int(round(f)):,}"
    return f"{f:,.{d}f}"


def nk(k):
    return str(k).strip().lower().replace("_", " ").replace("-", " ")


def pj(p):
    try:
        with open(p, encoding="utf-8-sig", errors="replace") as fh:
            d = json.load(fh)
    except Exception:
        return []
    rs = []
    if isinstance(d, list):
        rs = [r for r in d if isinstance(r, dict)]
    elif isinstance(d, dict):
        for v in d.values():
            if isinstance(v, list) and v and isinstance(v[0], dict):
                rs = [r for r in v if isinstance(r, dict)]
                break
        else:
            ks = [k for k, v in d.items() if isinstance(v, list)]
            if ks:
                n = max(len(d[k]) for k in ks)
                rs = [{k: (d[k][i] if i < len(d[k]) else None) for k in d} for i in range(n)]
            else:
                rs = [d]
    return [{nk(k): v for k, v in r.items() if k is not None} for r in rs]


def pc(p):
    try:
        with open(p, encoding="utf-8-sig", errors="replace", newline="") as fh:
            s = fh.read(8192)
            fh.seek(0)
            try:
                dl = csv.Sniffer().sniff(s, delimiters=",;\t|")
            except csv.Error:
                dl = csv.excel
            rd = csv.DictReader(fh, dialect=dl)
            if rd.fieldnames is None:
                return []
            rs = [r for r in rd if any(str(v).strip() != "" for v in r.values())]
    except Exception:
        return []
    return [{nk(k): v for k, v in r.items() if k is not None} for r in rs]


def pt(p):
    try:
        with open(p, encoding="utf-8-sig", errors="replace") as fh:
            ls = [l.strip() for l in fh if l.strip()]
    except Exception:
        return []
    out, cur = [], {}
    for l in ls:
        if ":" in l:
            k, _, v = l.partition(":")
            k = nk(k)
            if k:
                cur[k] = v.strip()
        elif cur:
            out.append(cur)
            cur = {}
    if cur:
        out.append(cur)
    return out


def find():
    fs = []
    for p in sorted(WS.iterdir()):
        if not p.is_file() or p.name in {Path(__file__).name, OUT.name}:
            continue
        if p.suffix.lower() not in {".csv", ".tsv", ".tab", ".txt", ".json", ".jsonl"}:
            continue
        rs = pj(p) if p.suffix.lower() in {".json", ".jsonl"} else []
        if not rs and p.suffix.lower() in {".csv", ".tsv", ".tab", ".txt"}:
            rs = pc(p)
        if not rs and p.suffix.lower() == ".txt":
            rs = pt(p)
        if not rs:
            continue
        cs = {}
        for r in rs:
            for k, v in r.items():
                cs.setdefault(k, []).append(v)
        nc = [k for k, vs in cs.items() if any(nf(v) is not None for v in vs)]
        if not nc:
            continue
        nm = p.name.lower()
        tx = nm + "\n" + "\n".join(" ".join(str(v) for v in r.values()) for r in rs[:30])
        eu = any(w in nm for w in EU) or sum(1 for w in EU if w in tx.lower()) >= 2
        fs.append({"p": p, "r": rs, "nc": nc, "eu": eu})
    return fs


def primary(fs):
    return max(fs, key=lambda f: (1000 if f["eu"] else 0) + 10 * len(f["nc"]) + min(len(f["r"]), 5000)) if fs else None


def story(pr, fs):
    rs = pr["r"]
    num = set(pr["nc"])
    ec = tc = None
    for c in rs[0].keys():
        if c in num:
            continue
        l = c.lower()
        if ec is None and any(h in l for h in ["country", "nation", "state", "region", "entity", "economy"]):
            ec = c
        elif tc is None and any(h in l for h in ["year", "quarter", "period", "date", "time", "month"]):
            tc = c
    ms = [c for c in pr["nc"] if c != ec and c != tc]

    def sers(m):
        s = [(r.get(tc) if tc else None, nf(r.get(m))) for r in rs]
        s = [(t, v) for t, v in s if v is not None]
        if tc:
            def sk(x):
                try:
                    return (0, float(x[0]))
                except (TypeError, ValueError):
                    return (1, str(x[0]))
            s.sort(key=sk)
        return s

    def lpe(m):
        o = {}
        for r in rs:
            e = r.get(ec)
            v = nf(r.get(m))
            if e is None or v is None or not str(e).strip():
                continue
            t = r.get(tc) if tc else None
            k = str(e).strip()
            if k not in o:
                o[k] = (t, v)
            else:
                try:
                    if t is not None and o[k][0] is not None and float(t) >= float(o[k][0]):
                        o[k] = (t, v)
                except (TypeError, ValueError):
                    pass
        return o

    st = {}
    for m in ms:
        s = sers(m)
        if len(s) < 2:
            continue
        pct = ((s[-1][1] - s[0][1]) / abs(s[0][1]) * 100.0) if s[0][1] else None
        st[m] = {"f": s[0][1], "l": s[-1][1], "pct": pct, "n": len(s),
                 "e": lpe(m) if ec else {}}

    def pick(kind):
        c = []
        for m, s in st.items():
            if kind == "h" and len(s["e"]) >= 2:
                vs = [v for _, v in s["e"].values()]
                c.append((max(vs) - min(vs), abs(s["pct"] or 0.0), m))
            elif kind == "f":
                c.append((abs(s["pct"]), m))
        return (max(c, key=lambda x: (x[0], x[1]))[2] if kind == "h" and c else
                (max(c)[1] if kind == "f" and c else None))

    h, f = pick("h"), pick("f")
    if h is None or not st:
        L = ["# European Economic Performance — Data Storytelling Report", "",
             "## The data", "",
             f"The primary dataset (`{pr['p'].name}`) has **{len(rs)} rows**; numeric columns: {', '.join(pr['nc'])}.", "",
             "Not enough structure was detected (at least two observations per indicator) for a trend or comparison narrative.", ""]
        L += appx(pr, fs)
        return "\n".join(L)

    s = st[h]
    es = s["e"]
    vs = [v for _, v in es.values()]
    tp = max(es, key=lambda k: es[k][1])
    bt = min(es, key=lambda k: es[k][1])
    tv, bv = es[tp][1], es[bt][1]
    gp = (tv - bv) / abs(bv) * 100.0 if bv else None
    md = statistics.median(vs)
    bl = sum(1 for v in vs if v <= md)
    tmd = (tv - md) / abs(md) * 100.0 if md else None
    bmd = (bv - md) / abs(md) * 100.0 if md else None
    fv = st[f]["pct"]
    ne = len(es)

    L = ["# European Economic Performance — Data Storytelling Report", "",
         "## The Hook", ""]
    if ne >= 2:
        L.append(f"European economic performance is **not one story but a split screen**: in the latest period, **{tp}** posted **{fm(tv)}** on *{h}* while **{bt}** sat at **{fm(bv)}** — a gap of **{fm(tv - bv)} ({fm(gp, 1)}%)** across the {ne} economies covered.")
    else:
        L.append(f"The headline number for *{h}* moved from **{fm(s['f'])}** to **{fm(s['l'])}** ({fm(s['pct'], 1)}%) over the observation period.")
    L += ["", "## The Context", "",
          f"The picture is built from **{len(rs)} data points** across **{ne} European economies**. The median value of *{h}* is **{fm(md)}**, so the leader runs **{fm(tmd, 1)}% above** the typical economy while the laggard sits **{fm(bmd, 1)}% below** it — the baseline is not a plateau, it is a slope.",
          "", "## The Conflict", "",
          f"The headline hides a structural problem: **{bl} of {ne} economies ({fm(bl / ne * 100.0, 0)}%)** sit at or below the median on *{h}*. The fastest-moving metric is *{f}*, which swung **{fm(fv, 1)}%** over the period — an early-warning signal that the gap may widen before it narrows.",
          "", "## The Insight", "",
          f"### Where the economies stand (latest period, *{h}*)", "", "```"]
    pairs = sorted(es.items(), key=lambda x: x[1][1], reverse=True)
    lo, hi = min(vs), max(vs)
    d = hi - lo
    for nm2, (_t, v) in pairs:
        n = 1 if d == 0 else max(1, int(round((v - lo) / d * 24)) + 1)
        L.append(f"  {str(nm2)[:22]:<22} |{'#' * n:<26}| {fm(v)}")
    L += ["```", "", "### Ranking table", "", "| Rank | Economy | Value |", "|---|---|---|"]
    for i, (nm2, (_t, v)) in enumerate(pairs, 1):
        L.append(f"| {i} | {nm2} | {fm(v)} |")
    L += ["", "### How the indicators moved over the period", "",
          "| Indicator | First | Latest | Change | % Change | Observations |", "|---|---|---|---|---|---|"]
    for m, x in sorted(st.items(), key=lambda kv: abs(kv[1]["pct"] or 0.0), reverse=True):
        L.append(f"| {m} | {fm(x['f'])} | {fm(x['l'])} | {fm(x['l'] - x['f'])} | {fm(x['pct'], 1)}% | {x['n']} |")
    L += ["", f"**Read the pattern:** the widest divergence sits on *{h}*; the momentum leader is *{f}*. Together they define the narrative: where you stand on {h} today, and which way {f} is pulling you.",
          "", "## The Recommendation", "",
          "Three levers follow directly from the data:", ""]
    if ne >= 2:
        L.append(f"1. **Learn from the leader.** {tp} holds a {fm(tmd, 1)}% edge over the median on *{h}* ({fm(tv)} vs. {fm(md)}). Investigate which policies, endowments, or exposures explain that lead and test them where the gap is widest ({bt} and peers).")
    L.append(f"2. **Manage the fastest-moving metric.** *{f}* changed by {fm(fv, 1)}% across the period. Track it monthly rather than quarterly and set a trigger threshold before the swing compounds.")
    if ne >= 2:
        L.append(f"3. **Raise the floor, not just the ceiling.** {bl} of {ne} economies trail the median; set {fm(md)} on *{h}* as the near-term benchmark for the laggards.")
    half = (tv - md) / 2
    L += ["", "### Expected impact", "",
          f"- **Leader replication** converts the leader's edge into a template: closing half the gap between median and leader lifts the median by **{fm(half)} points** (from {fm(md)} to {fm(md + half)}).",
          f"- **Early-warning tracking** on *{f}* buys a quarter of reaction time before the divergence widens further.",
          "- **Benchmarking laggards** at the median is measurable, credible, and within reach of existing data collection.",
          "", "## Call to Action", "",
          "**The ask:** pick one of the three levers above to fund this quarter — leader replication, early-warning tracking, or laggard uplift — and commission a monthly follow-up on this same dataset so the narrative is re-tested against new observations. The data has told us where the story is; the decision is which chapter to write next.",
          "", "---", ""]
    L += appx(pr, fs)
    return "\n".join(L)


def appx(pr, fs):
    L = ["## Appendix — Data & Method", "", "| File | Rows | Numeric columns | Europe match |", "|---|---|---|---|"]
    for f in fs:
        L.append(f"| {f['p'].name} | {len(f['r'])} | {', '.join(f['nc'])} | {'yes' if f['eu'] else 'no'} |")
    L += ["", f"**Primary dataset used:** `{pr['p'].name}` (highest Europe-relevance score, then row count and indicator count).",
          "", "**Limitations:** values are the latest observation per economy; indicator sample sizes are in the trend table; divergence shows correlation, not causation — recommendations are hypotheses to validate.",
          "", "_Generated by the task-scoped report builder from files found in the workspace directory._"]
    return L


def main():
    argv = [a for a in sys.argv[1:] if a]
    if argv and argv[0] not in {"create", "generate", "build"}:
        print(f"Unknown mode: {argv[0]}", file=sys.stderr)
        return 2
    if len(argv) > 1:
        global OUT
        OUT = WS / argv[1]
    fs = find()
    pr = primary(fs)
    if pr:
        rep = story(pr, fs)
    else:
        rep = "# European Economic Performance — Data Storytelling Report\n\n## The Hook\n\n**No European economic performance dataset was located in this directory.** Add a plain-text dataset (CSV/JSON) with columns such as `Country`, `Year`, and indicators (GDP, growth, inflation, unemployment, debt), then re-run the report builder."
    OUT.write_text(rep, encoding="utf-8")
    print("FOUND DATA FILES:")
    for f in fs:
        print(f"  - {f['p'].name} (rows={len(f['r'])}, numeric={len(f['nc'])}, europe_match={f['eu']})")
    if not fs:
        print("  (none)")
    if pr:
        print(f"PRIMARY DATASET : {pr['p'].name}")
    print(f"REPORT WRITTEN  : {OUT}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
